<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('finance.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'invoices');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$a=fpost('action');if($a==='invoice'){$cust=fint('customer_id');$project=fint('project_id');$amount=fnum('total_amount');$pdo->prepare('INSERT INTO invoices(invoice_no,customer_id,project_id,status,issue_date,due_date,subtotal,total_amount,balance_amount,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([op_code('INV'),$cust,$project,'issued',date('Y-m-d'),fpost('due_date')?:null,$amount,$amount,$amount,$staff['id']]);flash('success','Invoice created.');}elseif($a==='payment'){$inv=fint('invoice_id');$amt=fnum('amount');$invoice=db_one($pdo,'SELECT customer_id,project_id FROM invoices WHERE id=?',[$inv]);if($invoice){$pdo->prepare('INSERT INTO payments(payment_no,customer_id,project_id,payment_date,amount,payment_method,reference_no,status,notes,received_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([op_code('PAY'),$invoice['customer_id'],$invoice['project_id'],date('Y-m-d'),$amt,fpost('payment_method','bank_transfer'),fpost('reference_no')?:null,'received',fpost('notes')?:null,$staff['id']]);$pay=$pdo->lastInsertId();$pdo->prepare('INSERT INTO payment_allocations(payment_id,invoice_id,amount) VALUES(?,?,?)')->execute([$pay,$inv,$amt]);$pdo->prepare('UPDATE invoices SET paid_amount=paid_amount+?,balance_amount=GREATEST(total_amount-(paid_amount+?),0),status=IF(paid_amount+?>=total_amount,"paid","partially_paid") WHERE id=?')->execute([$amt,$amt,$amt,$inv]);flash('success','Payment recorded.');}}staff_redirect('staff/pages/finance.php');}
$customers=customer_options($pdo);$projects=project_options($pdo);$invoices=db_rows($pdo,'SELECT i.*,c.name customer_name,p.project_code FROM invoices i JOIN customers c ON c.id=i.customer_id LEFT JOIN projects p ON p.id=i.project_id ORDER BY i.created_at DESC');$pageTitle='Payments & Invoices';require __DIR__.'/../../includes/staff/header.php';module_head('Finance','Payments & Invoices','Track customer billing, deposits, progress payments and outstanding balances.');?>
<div class="split-grid"><section class="staff-panel"><h2>Create invoice</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="invoice"><label>Customer<select name="customer_id"><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach?></select></label><label>Project<select name="project_id"><option value="">None</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=h($p['project_code'].' · '.$p['name'])?></option><?php endforeach?></select></label><div class="two"><label>Total (RM)<input type="number" step=".01" name="total_amount" required></label><label>Due date<input type="date" name="due_date"></label></div><button class="btn primary">Issue invoice</button></form></section><section class="staff-panel"><h2>Record payment</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="payment"><label>Invoice<select name="invoice_id"><?php foreach($invoices as $i):?><option value="<?=$i['id']?>"><?=h($i['invoice_no'].' · '.$i['customer_name'].' · RM '.number_format($i['balance_amount'],2))?></option><?php endforeach?></select></label><div class="two"><label>Amount<input type="number" step=".01" name="amount" required></label><label>Method<select name="payment_method"><option>bank_transfer</option><option>cash</option><option>card</option><option>cheque</option><option>other</option></select></label></div><label>Reference<input name="reference_no"></label><button class="btn">Record payment</button></form></section></div><section class="staff-panel table-panel"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Project</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php foreach($invoices as $i):?><tr><td><b><?=h($i['invoice_no'])?></b></td><td><?=h($i['customer_name'])?></td><td><?=h($i['project_code']?:'—')?></td><td>RM <?=number_format($i['total_amount'],2)?></td><td>RM <?=number_format($i['paid_amount'],2)?></td><td>RM <?=number_format($i['balance_amount'],2)?></td><td><span class="pill"><?=h($i['status'])?></span></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>